/**
 * Keeps only the newest request alive: every `run()` aborts whatever the previous one started,
 * so a slow earlier response can never overwrite a newer one.
 *
 * @example
 * private request = new LatestRequest();
 * const { aborted, result } = await this.request.run(signal => salla.order.api.getShipments(id, signal));
 * if (aborted) return;
 */
export class LatestRequest {
    /** `aborted` is true when a newer run (or `abort()`) superseded this one; `result` is then undefined. */
    async run(fn) {
        this.abort();
        const { signal } = (this.controller = new AbortController());
        try {
            const result = await fn(signal);
            return signal.aborted ? { aborted: true } : { aborted: false, result };
        }
        catch (error) {
            if (signal.aborted)
                return { aborted: true };
            throw error;
        }
    }
    abort() {
        this.controller?.abort();
    }
}
